  try {
    var data = JSON.parse(e.postData.contents);
    
    if (data.to && data.subject && data.htmlBody) {
      GmailApp.sendEmail(data.to, data.subject, data.plainText || "", {
        htmlBody: data.htmlBody,
        name: "SKY Meditation at UIUC",
        replyTo: "skyatuiuc@gmail.com"
      });
      
      return ContentService.createTextOutput(JSON.stringify({ status: "success" }))
        .setMimeType(ContentService.MimeType.JSON);
    }
    
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: "Missing required fields" }))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
